#include <iostream>
#include <string>
#include <chrono>

#include "encoder.h"
#include "HV.h"

int main() {
    // Cache can hold a few entries for the test
    HVCache cache(10000);


    std::vector<std::string> queries = {
        "AGGGGCATGATGATTTGACGTCATCCCCACCTTCCTCCGAGTTAACCCCGGCAGTCTCGCTAGAGTGCTCAACTGAATGGTAGCAACTAACAATAAGGGTTGCGCTCGTTGCGGGACTTAACCCA"
    };
    std::vector<std::string> refs = {
        "",
        "",
        "",
        ""
    };
    int index = 0;
    //std::string query = "TTTGAGTTTTAATCTTGCGACCGTACTCCCCAGGCGGAATACTTAATGTGTTAACGGCGGCACGGAAGGTTTGGTACCTCCCACACCTAGTATTCATCGTTTACG";
    for(auto &ref: refs) {
        cache.precompute(ref);
        int i2 = 0;
        for (auto &ref2: queries) {
            auto sim = cache.similarity(ref2, ref);
            std::cout << "\nRef " << std::to_string(index) << "/" << std::to_string(i2) << ": " << std::to_string(sim.score) << " @" << std::to_string(sim.pos);
            i2++;
        }
        index++;
    }
}